package io.github.diodeme.ji.host;

import java.time.Instant;
import java.util.Set;

/** Short-lived authenticated transport identity consumed by Host application commands. */
public record ConnectionPrincipal(
        String connectionId,
        String clientId,
        String deviceId,
        String hostId,
        String transport,
        String routeId,
        HostRole role,
        Set<String> scopes,
        Instant authenticatedAt) {
    public ConnectionPrincipal {
        connectionId = required(connectionId, "connectionId");
        clientId = required(clientId, "clientId");
        deviceId = required(deviceId, "deviceId");
        hostId = required(hostId, "hostId");
        transport = required(transport, "transport");
        routeId = routeId == null ? "" : routeId;
        java.util.Objects.requireNonNull(role, "role");
        scopes = Set.copyOf(scopes);
        if (!role.scopes().containsAll(scopes)) throw new IllegalArgumentException("scope exceeds Host role");
        java.util.Objects.requireNonNull(authenticatedAt, "authenticatedAt");
    }

    public void require(String scope) {
        if (!scopes.contains(scope)) throw new SecurityException("Host scope denied");
    }

    public static ConnectionPrincipal localAdmin(String connectionId, String clientId, String hostId) {
        return new ConnectionPrincipal(connectionId, clientId, clientId, hostId, "direct", "",
                HostRole.HOST_ADMIN, HostRole.HOST_ADMIN.scopes(), Instant.now());
    }

    private static String required(String value, String name) {
        if (value == null || value.isBlank()) throw new IllegalArgumentException(name + " must not be blank");
        return value;
    }
}
